    {
     "title": "7. Cleanup",
     "cmds": [
      {
       "d": "Delete everything this example created",
       "c": "gcloud api-gateway gateways delete petshop-gw --location=$REGION --quiet\ngcloud api-gateway api-configs delete v1 --api=petshop-api --quiet\ngcloud api-gateway apis delete petshop-api --quiet\ngcloud services api-keys delete $KEY_NAME --quiet\ngcloud functions delete petsApi --region=$REGION --quiet\ngcloud functions delete onAdoption --region=$REGION --quiet\ngcloud pubsub topics delete adoptions --quiet\ngcloud storage rm --recursive gs://$PROJECT_ID-pet-photos\nfor sa in petshop-api petshop-worker petshop-gateway; do gcloud iam service-accounts delete $sa@$PROJECT_ID.iam.gserviceaccount.com --quiet; done"
      }
     ]
    }
